cd /workspace && python3 - <<'PY'
import sys,random,time,networkx as nx
sys.path.insert(0,'/workspace/submission');sys.path.insert(0,'/workspace/tmp')
from fastgen import fast_generate,FastGenFailure
from testgen import cuts_ok
random.seed(4242)
for n in range(2,13):
 for it in range(1500):
  G=nx.DiGraph();G.add_nodes_from(range(n))
  for u in range(n):
   for v in range(n):
    if u!=v and random.random()<0.35:
     G.add_edge(u,v,capacity=random.randint(1,8))
  roots={i:random.choice([0,0,1,2,3,5]) for i in range(n)}
  if sum(roots.values())==0:roots[random.randrange(n)]=1
  ok,_=cuts_ok(G,roots)
  if not ok:continue
  try:
   Ts,Cs=fast_generate(G,list(range(n)),roots)
  except Exception as e:
   print('FAST FAIL',n,it,roots,sorted(G.edges(data=True)),repr(e));raise
  agg={}
  for (r,i),T in Ts.items():
   assert len(T)==n-1 and len(set(T))==n-1
   for a,b in T:agg[(a,b)]=agg.get((a,b),0)+Cs[(r,i)]
  for (a,b),c in agg.items():assert c<=G[a][b]['capacity'],((a,b),c)
  for u,c in roots.items():assert sum(v for (r,i),v in Cs.items() if r==u)==c
 print('n',n,'ok')
print('ALL FAST OK')
